WITH metrics AS (SELECT *, MIN(price) OVER w_grp AS running_min_price, AVG(price) OVER w_grp AS running_avg_price, MAX(price) OVER w_grp AS running_max_price, COUNT(price) OVER w_grp AS running_count_price, SUM(price) OVER (PARTITION BY category, brand) AS category_sum_price FROM products WINDOW w_grp AS (PARTITION BY category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), joined AS (SELECT s.*, d.supplier_name, d.country FROM metrics s LEFT JOIN suppliers d ON s.supplier_id = d.id WHERE d.rating >= 4.1), latest AS (SELECT id, product_name, stock_qty, launch_date, tags, supplier_id, running_min_price, running_max_price, supplier_name, country FROM joined QUALIFY ROW_NUMBER() OVER (PARTITION BY brand ORDER BY category_sum_price DESC NULLS FIRST, id) = 1), with_last AS (SELECT s.*, x.store_sale_revenue, x.store_sale_sale_date FROM latest s LEFT JOIN LATERAL (SELECT c.revenue AS store_sale_revenue, c.sale_date AS store_sale_sale_date FROM store_sales c WHERE c.product_id = s.id ORDER BY c.revenue DESC, c.id DESC LIMIT 1) x ON TRUE), scored AS (SELECT id, product_name, country, store_sale_revenue, COUNT(running_max_price) OVER (PARTITION BY supplier_id ORDER BY store_sale_revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_running_max_price, SUM(running_max_price) OVER (PARTITION BY supplier_id ORDER BY store_sale_revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_running_max_price, MAX(running_max_price) OVER (PARTITION BY supplier_id ORDER BY store_sale_revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_running_max_price, MIN(running_max_price) OVER (PARTITION BY supplier_id ORDER BY store_sale_revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_running_max_price, ROW_NUMBER() OVER (PARTITION BY country, supplier_id ORDER BY store_sale_revenue, id) AS seq_no FROM with_last), with_windows AS (SELECT *, ROW_NUMBER() OVER w_running AS event_seq, ROW_NUMBER() OVER (ORDER BY seq_no, id) AS row_seq, SUM(running_count_running_max_price) OVER (ORDER BY running_count_running_max_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_running_count_running_max_price, ROUND(running_sum_running_max_price / SUM(running_sum_running_max_price) OVER (PARTITION BY country), 4) AS running_sum_running_max_price_share, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY country ORDER BY seq_no, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country FROM scored WINDOW w_running AS (PARTITION BY country ORDER BY running_min_running_max_price, id)), stats AS (SELECT seq_no, CASE WHEN running_sum_running_max_price_share >= 0.77 THEN 'HIGH' ELSE 'LOW' END AS running_sum_running_max_price_share_tier, COUNT(*) AS row_count, APPROX_PERCENTILE(seq_no, 0.95) AS seq_no_p95, AVG(running_count_running_max_price) AS avg_running_count_running_max_price, SORT_ARRAY(COLLECT_SET(country)) AS country_list FROM with_windows GROUP BY seq_no, CASE WHEN running_sum_running_max_price_share >= 0.77 THEN 'HIGH' ELSE 'LOW' END) SELECT seq_no, running_sum_running_max_price_share_tier, row_count, seq_no_p95, country_list FROM stats ORDER BY seq_no DESC;
